package com.ranjith.arena.service;
import com.fasterxml.jackson.databind.JsonNode; import com.ranjith.arena.model.*; import com.ranjith.arena.repository.*; import org.springframework.stereotype.Service; import java.util.*; import java.util.regex.*;
@Service public class EvaluationService { private final MessageRepo messages; private final EvaluationRepo evals; private final SessionRepo sessions; private final ResumeRepo resumes; private final AiRecruiterService ai;
 public EvaluationService(MessageRepo m,EvaluationRepo e,SessionRepo s,ResumeRepo r,AiRecruiterService a){messages=m;evals=e;sessions=s;resumes=r;ai=a;}
 public InterviewEvaluation evaluate(Long sid){ InterviewSession sess=sessions.findById(sid).orElseThrow(); String resume=sess.getResumeId()==null?"":resumes.findById(sess.getResumeId()).map(Resume::getExtractedText).orElse(""); List<InterviewMessage> all=messages.findBySessionIdOrderByCreatedAtAsc(sid); JsonNode j=ai.finalEvaluation(sess.getCandidateName(),sess.getRole(),resume,all); InterviewEvaluation e=evals.findBySessionId(sid).orElseGet(InterviewEvaluation::new);e.setSessionId(sid);e.setTechnicalScore(score(j,"technical"));e.setCommunicationScore(score(j,"communication"));e.setRelevanceScore(score(j,"relevance"));e.setProjectScore(score(j,"project"));e.setProblemSolvingScore(score(j,"problemSolving"));e.setOverallScore(score(j,"overall"));String joined=all.stream().filter(x->"candidate".equalsIgnoreCase(x.getSpeaker())).map(InterviewMessage::getMessage).filter(Objects::nonNull).reduce("",(a,b)->a+" "+b).toLowerCase();e.setFillerWords(count(joined,"um")+count(joined,"uh")+count(joined,"like")+count(joined,"actually"));e.setLongPauses(0);e.setAverageResponseSeconds(0);e.setStrengths(j.path("strengths").asText("Not enough evidence."));e.setImprovements(j.path("improvements").asText("Not enough evidence."));e.setRecommendation(j.path("recommendation").asText("Complete more interview questions for a detailed recommendation."));return evals.save(e); }
 private int score(JsonNode j,String k){return Math.max(0,Math.min(100,j.path(k).asInt(0)));} private int count(String s,String x){return (int)Pattern.compile("\\b"+Pattern.quote(x)+"\\b").matcher(s).results().count();}
}
